    "security.vulns.ack_intro": "Une faille sans correctif que vous jugez sans importance pour vous peut être ignorée : elle ne compte plus dans la couleur du bouclier, le score ni la vue simple, et reste consultable dans « Failles ignorées ». Les nouvelles failles publiées ensuite sont toujours affichées.",
