    "security.vulns.acked_list": "Failles ignorées ({n})",
    "security.vulns.cve.tunnelvision": "« TunnelVision » : défaut de conception du DHCP (option 121), pas un bogue de ce paquet ; aucun correctif possible, Ubuntu la classe « deferred ». Risque uniquement sur un réseau non maîtrisé (Wi-Fi public) où un faux serveur DHCP peut détourner le trafic hors du tunnel. Vous avez un VPN configuré ({vpns}) : sur un réseau public, coupez le Wi-Fi si le VPN tombe, ou utilisez un VPN avec « kill switch » (pare-feu n'autorisant que le serveur VPN).",
    "security.vulns.cve.tunnelvision_novpn": "« TunnelVision » : défaut de conception du DHCP (option 121), pas un bogue de ce paquet ; aucun correctif possible, Ubuntu la classe « deferred ». Elle ne concerne que les connexions VPN, et aucun VPN n'est configuré sur cet ordinateur : sans effet en pratique.",
