    "security.vulns.hwe_badge": "corrigée dans le noyau HWE ({pkg})",
    "security.vulns.hwe_note": "{n} failles concernent le noyau 6.8 livré avec Linux Mint et sont déjà corrigées dans un noyau HWE plus récent (6.11 ou 6.14). Ubuntu ne les corrigera pas toutes dans le 6.8 : la solution est d'installer le noyau HWE (Gestionnaire de mises à jour → Affichage → Noyaux Linux, ou « sudo apt install linux-generic-hwe-24.04 »).",
    "security.vulns.intro": "« Sans correctif » : Ubuntu n'a pas encore publié de correctif pour ce paquet dans cette version du système ; il n'y a rien à installer, et la plupart sont de priorité moyenne ou basse. Une faille déjà corrigée dans la version installée n'apparaît pas. « Correctif disponible » : une mise à jour l'installe.",
    "security.vulns.kernel_note": "{n} failles concernent le noyau en cours d'exécution ({src} {release}) : Ubuntu n'a pas encore publié de correctif, elles seront corrigées par les mises à jour du système, rien à faire de votre côté. Elles ne comptent pas dans « Sans correctif ».",
    "security.vulns.kernel_pending": "Noyau (correctif attendu)",
    "security.vulns.na_note": "{n} failles concernent {pkgs} : le moteur JavaScript extrait de Firefox ESR, utilisé par {users}. Ce n'est pas votre navigateur (Firefox se met à jour à part). Elles décrivent des parties du navigateur absentes du moteur seul (contenu web, animations, médias, onglets…) et Ubuntu ne les corrige pas dans ce paquet : elles ne comptent pas dans « Sans correctif ». Les failles propres au moteur (JIT, WebAssembly, ramasse-miettes) restent dans « Sans correctif ».",
