    "backup.timeshift.enable_hint": "One click, no password: Timeshift photographs the system every day and keeps 5 days, 3 weeks and 2 months of snapshots on the main disk. Your documents and personal settings are not included (that's the backup's job), only the system: after a failed update or an infection, you go back to yesterday's state. The app first checks there is enough room (1.2 × the system + 10 GB) and suspends snapshots if the disk drops below 10 GB free. Disabling requires the administrator password.",
