    "legal.accept": "I have read and accept",
    "legal.footer": "This text is also available under Credits → Disclaimer.",
    "legal.link": "Disclaimer",
    "legal.p1": "ClamAV Antivirus GUI (hereinafter “the Software”) is provided by Dukiwi SA “AS IS” and “AS AVAILABLE”, without warranty of any kind, express or implied, including but not limited to warranties of merchantability, fitness for a particular purpose, non-infringement, accuracy, reliability, availability or absence of errors. By installing or using the Software you accept this disclaimer without reservation.",
    "legal.p10": "Dukiwi SA guarantees neither the continuity, the durability nor the frequency of updates of the Software, of the signatures or of the information sources, and may discontinue them at any time without notice or compensation. The Software may contain errors; any correction is made at Dukiwi SA's discretion, without obligation.",
    "legal.p11": "The Software integrates or uses third-party components (in particular ClamAV, UFW, Lynis, unhide, chkrootkit, debsums, Python and GTK libraries) subject to their own licences and terms. Trademarks and product names mentioned belong to their respective owners. Dukiwi SA is neither affiliated with Cisco Talos / ClamAV nor responsible for these components.",
    "legal.p12": "If any provision of this disclaimer is held invalid or unenforceable, the remaining provisions remain in full force and the provision concerned is deemed replaced by a valid provision of equivalent effect. This disclaimer is governed by Swiss law; any dispute falls under the exclusive jurisdiction of the courts of Dukiwi SA's registered seat, subject to mandatory provisions to the contrary. If you do not accept these terms, do not install or use the Software.",
    "legal.p2": "The Software is an assistance tool and constitutes at most a first barrier. It relies on the open-source ClamAV engine, on signature databases and on third-party information sources (Ubuntu, OSV.dev, blocklists, geolocation services) over which Dukiwi SA has no control. No antivirus, firewall or detection tool can identify every threat; new or targeted malware may go undetected, and legitimate programs may be wrongly flagged (false positives).",
    "legal.p3": "A “no threat detected” result, a green indicator, a score, a grade or any other information displayed by the Software is in no way a guarantee that your computer, data or network are clean, secure or compliant. This information is provided for guidance only and replaces neither a security audit, nor professional monitoring, nor your own vigilance.",
    "legal.p4": "Only careful and informed user behaviour (security awareness) genuinely limits the risks: reading before clicking, distrust of unusual messages, refusal of unknown attachments and media, strong passwords, regular offline backups, prompt installation of updates. The user remains solely responsible for their actions, their choices and the protection of their data.",
    "legal.p5": "TO THE FULLEST EXTENT PERMITTED BY APPLICABLE LAW, DUKIWI SA, ITS DIRECTORS, EMPLOYEES, AGENTS, PARTNERS AND CONTRIBUTORS SHALL IN NO EVENT BE LIABLE for any direct, indirect, incidental, special, consequential, punitive or exemplary damages, including but not limited to: loss, alteration, encryption or disclosure of data; loss of profits, revenue, customers or business; business interruption; replacement costs; damage to reputation; arising from or related to the use of or inability to use the Software, even if Dukiwi SA has been advised of the possibility of such damages.",
    "legal.p6": "This exclusion covers in particular, without limitation: any infection by a virus, worm, trojan horse, ransomware (cryptolocker), spyware or other malicious code, whether detected or not; any hacking, intrusion, unauthorised access, phishing, CEO fraud, social engineering or identity theft; any exploitation of a security vulnerability, whether fixed or not, known or not; any loss of data resulting from a quarantine, a deletion, a process termination, a firewall rule or any other action triggered by the Software or by the user.",
    "legal.p7": "Depending on the configuration chosen by the user, the Software may perform actions affecting the system: suspending or terminating processes, quarantining or moving files, enabling the firewall and blocking connections, installing updates, blocking access to removable media. The user acknowledges that these actions may disrupt legitimate programs or cause data loss and assumes full responsibility for them. It is the user's duty to hold complete, verified backups before any use.",
    "legal.p8": "Dukiwi SA is not liable for any inappropriate, negligent, diverted, unlawful use of the Software or use contrary to this disclaimer, nor for the consequences of the deactivation, modification or circumvention of its protections by the user, an administrator or a third party. The Software must not be used as the sole protective measure in an environment where a failure could cause bodily, material, financial or environmental harm.",
    "legal.p9": "The Software is neither designed nor certified to guarantee compliance with any legal, regulatory or contractual obligation (data protection, professional secrecy, industry standards, insurance requirements…). It is up to the user or their organisation to define and implement the security measures appropriate to their situation and to verify their adequacy.",
    "legal.title": "Disclaimer and limitation of liability",
