    "security.vulns.cve.tunnelvision": "“TunnelVision”: a DHCP design flaw (option 121), not a bug in this package; no fix is possible, Ubuntu marks it “deferred”. Risk only on an untrusted network (public Wi-Fi) where a rogue DHCP server can pull traffic out of the tunnel. You have a VPN configured ({vpns}): on a public network, cut the Wi-Fi if the VPN drops, or use a VPN with a kill switch (firewall allowing only the VPN server).",
