    "security.vulns.na_note": "{n} vulnerabilities concern {pkgs}: the JavaScript engine extracted from Firefox ESR, used by {users}. It is not your browser (Firefox updates separately). They describe browser parts absent from the engine alone (web content, animations, media, tabs…) and Ubuntu does not fix them in this package: they are not counted in “Unfixed”. Engine-specific flaws (JIT, WebAssembly, garbage collector) stay under “Unfixed”.",
