    "backup.timeshift.enable": "Schnappschüsse aktivieren (empfohlen)",
    "backup.timeshift.enable_hint": "Ein Klick, kein Passwort: Timeshift fotografiert das System täglich und behält 5 Tage, 3 Wochen und 2 Monate an Schnappschüssen auf der Hauptfestplatte. Ihre Dokumente und persönlichen Einstellungen sind nicht enthalten (dafür ist die Sicherung da), nur das System: nach einem fehlgeschlagenen Update oder einer Infektion kehren Sie zum Stand von gestern zurück. Die App prüft zuerst, ob genug Platz da ist (1,2 × das System + 10 GB), und setzt die Schnappschüsse aus, wenn weniger als 10 GB frei bleiben. Deaktivieren erfordert das Administratorpasswort.",
