    "check.auto_updates.fix": "„Aktivieren“ schaltet die Automatisierung der Aktualisierungsverwaltung ein (Korrekturen werden täglich ohne Ihr Zutun installiert), danach die automatischen Updates der Cinnamon-Spices und Flatpak-Apps, sofern vorhanden. Danach ist nichts mehr zu tun.",
