    "check.disk_encryption.fix": "Die Festplattenverschlüsselung (LUKS) schützt Ihre Daten bei Diebstahl des Rechners. Sie lässt sich nur bei der Installation von Linux Mint aktivieren („Neue Installation verschlüsseln“). Sonst zumindest sensible Ordner verschlüsseln (Cryptomator, VeraCrypt) und Backups behalten.",
