    "check.exposed_services.fix": "Dateifreigabe, Drucken, Datenbanken oder Remote-Desktop sind aus dem Netzwerk erreichbar. Dienst deaktivieren, wenn ungenutzt, oder mit einer Firewall-Regel auf das lokale Netz beschränken.",
