    "check.hardening.fix": "„Beheben“ öffnet die Liste der Lynis-Vorschläge: jede risikolose Empfehlung wird mit einem Klick oder alle zusammen angewendet, die übrigen werden erklärt. Der Index wird nach jeder Anwendung neu berechnet.",
