    "check.kernel_hwe.fix": "Die Distribution verwaltet die Kernel-Verteilung: Linux Mint bietet die HWE-Kernel (6.11, 6.14) in der Aktualisierungsverwaltung → Ansicht → Linux-Kernel an. Aus dieser Anwendung ist nichts zu installieren; folgen Sie den Empfehlungen von Mint.",
