    "check.kernel_hwe.title": "Kernel",
    "check.ld_preload.fix": "/etc/ld.so.preload zwingt jedem Programm eine Bibliothek auf: eine Rootkit-Technik. Integritätsprüfung starten, dann die Datei prüfen (sudo cat /etc/ld.so.preload) und löschen, wenn nicht gerechtfertigt.",
    "check.ld_preload.hint": "/etc/ld.so.preload existiert: klassische Rootkit-Technik, Inhalt prüfen",
    "check.ld_preload.ok": "Keine vorgeladene Bibliothek",
    "check.ld_preload.title": "System-Preload (ld.so.preload)",
    "check.nopasswd_sudo.fix": "Eine NOPASSWD-Regel in /etc/sudoers.d gewährt root ohne Passwort. Von einem Systempaket gelieferte (mintupdate, mintdrivers, mintsystem) und unveränderte Dateien sind normal und werden nicht gezählt. Bei einer von Hand hinzugefügten oder geänderten Datei: sudo visudo -f /etc/sudoers.d/NAME und NOPASSWD entfernen, oder das Originalpaket neu installieren.",
    "check.nopasswd_sudo.hint": "Eine von Hand hinzugefügte oder geänderte NOPASSWD-Regel gewährt root ohne Passwort",
