    "check.open_ports.fix": "Ein „erreichbarer“ Port nimmt Verbindungen aus dem Netzwerk an. Für jeden Port: Wird das Programm nicht gebraucht, stoppen Sie es (sudo systemctl disable --now DIENST); sonst Port mit der Schaltfläche blockieren oder im Reiter Firewall auf das lokale Netz beschränken.",
