    "credits.app.p1": "Eine moderne grafische Oberfläche für ClamAV unter Linux. Sie vereinfacht die Verwaltung Ihres Virenschutzes: Signatur-Updates, Ordner-Scans, automatische Quarantäne und Systemüberwachung über ein Schild in der Taskleiste.",
    "credits.app.p2": "Ein Systemdienst (clamav-antivirus-daemon) führt vollständige Scans, geplante Updates, die Schreibüberwachung und die Prüfung von USB-Medien ohne Passwortabfrage aus.",
    "credits.clamav.daemon": "Daemon",
    "credits.clamav.daemon_text": "clamd — Hintergrunddienst für schnellere Scans über einen Socket, wird zur sofortigen Prüfung verdächtiger Programme genutzt.",
    "credits.clamav.db": "Datenbank",
    "credits.clamav.db_text": "Virensignaturen von Cisco Talos, täglich mit Millionen von Signaturen aktualisiert.",
    "credits.clamav.engine": "Scan-Engine",
    "credits.clamav.engine_text": "clamscan — Kommandozeilen-Scanner für Dateien und Ordner (rekursiv).",
    "credits.clamav.p1": "ClamAV ist eine Open-Source-Antiviren-Engine zur Erkennung von Trojanern, Viren, Malware und anderen Bedrohungen. Sie wird häufig auf Mailservern und als Virenschutz auf Unix/Linux-Systemen eingesetzt.",
    "credits.developer": "Entwickler",
    "credits.freshclam.auto": "Automatische Aktualisierung",
    "credits.freshclam.auto_text": "Der Dienst clamav-freshclam läuft im Hintergrund; ClamAV Antivirus GUI erzwingt zusätzlich eine Prüfung täglich um 07:00 Uhr und 5 Minuten nach jedem Start.",
    "credits.freshclam.config": "Konfiguration",
    "credits.freshclam.config_text": "Konfigurierbar über /etc/clamav/freshclam.conf — Häufigkeit, Spiegelserver, Proxy, Benachrichtigungen.",
    "credits.freshclam.db": "Datenbanken",
    "credits.freshclam.db_text": "main.cvd — Hauptdatenbank. daily.cvd — Tägliche Updates. bytecode.cvd — Erweiterte Bytecode-Signaturen.",
    "credits.freshclam.p1": "Freshclam ist das automatische Update-Werkzeug für die Virendatenbanken von ClamAV. Es lädt die neuesten Signaturen von den ClamAV-Spiegelservern.",
    "credits.licence.appindicator": "Taskleisten-Integration für Linux-Desktops (LGPL)",
    "credits.licence.distributed": "Veröffentlicht unter der",
    "credits.licence.gtk": "Natives GUI-Toolkit für Linux (LGPL)",
    "credits.licence.p1": "ClamAV steht unter der GPL v2 (GNU General Public License Version 2). ClamAV ist ein Projekt der Cisco Talos Intelligence Group.",
    "credits.licence.p2": "ClamAV Antivirus GUI (diese grafische Oberfläche) ist freie Software unter der GPL v3 (GNU General Public License Version 3), entwickelt von Dukiwi SA. Die Oberfläche nutzt folgende Komponenten:",
    "credits.licence.webkit": "Eingebettete Web-Rendering-Engine für die HTML/CSS/JS-Oberfläche (LGPL)",
    "credits.tab.licence": "Lizenz",
    "credits.title": "Danksagungen",
    "credits.website": "Offizielle Website:",
