    "security.integrity.hint.hidden_benign": "Normale versteckte Dateien: .build-id (Debug-Symbole), .packlist (Perl-Module)… chkrootkit meldet jeden Namen, der in /usr/lib und /lib mit einem Punkt beginnt. Wenn Sie alle diese Pfade kennen, klicken Sie auf „Das ist normal“: sie zählen dann nicht mehr.",
    "security.integrity.hint.hidden_check": "chkrootkit meldet jede versteckte Datei in /usr/lib und /lib. .build-id und .packlist sind normal; ein Pfad, den Sie nicht kennen, verdient eine Recherche (ein Rootkit versteckt seine Dateien so), bevor Sie auf „Das ist normal“ klicken.",
