    "security.vulns.ack": "Ignorieren",
    "security.vulns.ack_all": "Alle ignorieren ({n})",
    "security.vulns.ack_all_msg": "Diese {n} Schwachstellen ohne Korrektur zählen nicht mehr für die Schildfarbe, die Sicherheitspunktzahl oder die einfache Ansicht. Sie bleiben unter „Ignorierte Schwachstellen“ aufgeführt und können jederzeit wieder angezeigt werden. Später veröffentlichte Schwachstellen werden weiterhin gemeldet.",
    "security.vulns.ack_all_ok": "Ignorieren",
    "security.vulns.ack_all_title": "{n} Schwachstelle(n) ignorieren?",
    "security.vulns.ack_hint": "Diese Schwachstelle zählt nicht mehr für den Systemzustand (Schild, Punktzahl, einfache Ansicht)",
    "security.vulns.ack_intro": "Eine Schwachstelle ohne Korrektur, die Sie für unwichtig halten, kann ignoriert werden: sie zählt nicht mehr für die Schildfarbe, die Punktzahl oder die einfache Ansicht und bleibt unter „Ignorierte Schwachstellen“ einsehbar. Später veröffentlichte Schwachstellen werden immer angezeigt.",
    "security.vulns.acked": "Ignoriert",
    "security.vulns.acked_at": "ignoriert am {date}",
    "security.vulns.acked_intro": "Von Ihnen ignoriert: sie zählen nicht mehr für den Systemzustand.",
    "security.vulns.acked_list": "Ignorierte Schwachstellen ({n})",
    "security.vulns.cve.tunnelvision": "„TunnelVision“: ein Designfehler von DHCP (Option 121), kein Fehler dieses Pakets; keine Korrektur möglich, Ubuntu stuft sie als „deferred“ ein. Risiko nur in einem fremden Netz (öffentliches WLAN), wo ein gefälschter DHCP-Server Verkehr aus dem Tunnel ziehen kann. Sie haben ein VPN konfiguriert ({vpns}): in öffentlichen Netzen WLAN trennen, wenn das VPN abbricht, oder ein VPN mit Kill-Switch nutzen (Firewall lässt nur den VPN-Server zu).",
    "security.vulns.cve.tunnelvision_novpn": "„TunnelVision“: ein Designfehler von DHCP (Option 121), kein Fehler dieses Pakets; keine Korrektur möglich, Ubuntu stuft sie als „deferred“ ein. Sie betrifft nur VPN-Verbindungen, und auf diesem Rechner ist kein VPN konfiguriert: praktisch ohne Wirkung.",
    "security.vulns.embedded_badge": "eingebettete JS-Engine (Cinnamon), nicht Firefox oder Thunderbird",
    "security.vulns.error": "Fehler: {error}",
    "security.vulns.fix_available": "Korrektur verfügbar",
    "security.vulns.hidden": "{n} Lücke(n) niedrigerer Priorität ausgeblendet",
    "security.vulns.hwe_action": "Aktualisierungsverwaltung öffnen",
    "security.vulns.hwe_badge": "im HWE-Kernel behoben ({pkg})",
    "security.vulns.hwe_note": "{n} Lücken betreffen den mit Linux Mint gelieferten Kernel 6.8 und sind in einem neueren HWE-Kernel (6.11 oder 6.14) bereits behoben. Ubuntu wird nicht alle im 6.8 beheben: Die Lösung ist der HWE-Kernel (Aktualisierungsverwaltung → Ansicht → Linux-Kernel, oder „sudo apt install linux-generic-hwe-24.04“).",
    "security.vulns.intro": "„Ohne Korrektur“: Ubuntu hat für dieses Paket in dieser Systemversion noch keine Korrektur veröffentlicht; es gibt nichts zu installieren, und die meisten haben mittlere oder niedrige Priorität. Eine in der installierten Version bereits behobene Lücke wird nicht angezeigt. „Korrektur verfügbar“: ein Update installiert sie.",
    "security.vulns.kernel_note": "{n} Schwachstellen betreffen den laufenden Kernel ({src} {release}): Ubuntu hat noch keine Korrektur veröffentlicht, sie werden durch Systemupdates behoben, nichts zu tun Ihrerseits. Sie zählen nicht zu „Ohne Korrektur“.",
    "security.vulns.kernel_pending": "Kernel (Korrektur ausstehend)",
    "security.vulns.na_note": "{n} Schwachstellen betreffen {pkgs}: die aus Firefox ESR extrahierte JavaScript-Engine, genutzt von {users}. Das ist nicht Ihr Browser (Firefox aktualisiert sich separat). Sie beschreiben Browserteile, die der Engine allein fehlen (Webinhalte, Animationen, Medien, Tabs…), und Ubuntu behebt sie in diesem Paket nicht: sie zählen nicht zu „Ohne Korrektur“. Engine-eigene Fehler (JIT, WebAssembly, Garbage Collector) bleiben unter „Ohne Korrektur“.",
    "security.vulns.none_in_filter": "Keine Schwachstelle in dieser Kategorie.",
