    "credits.app.p1": "Un'interfaccia grafica moderna per ClamAV su Linux. Progettata per semplificare la gestione dell'antivirus: aggiornamento delle firme, scansione delle cartelle, quarantena automatica e monitoraggio del sistema tramite uno scudo nella barra delle applicazioni.",
    "credits.app.p2": "Un servizio di sistema (clamav-antivirus-daemon) esegue le scansioni complete, gli aggiornamenti pianificati, il monitoraggio delle scritture e l'analisi dei supporti USB senza chiedere la password.",
    "credits.clamav.daemon": "Daemon",
    "credits.clamav.daemon_text": "clamd — Servizio in background per scansioni più rapide tramite socket, usato per verificare all'istante i programmi sospetti.",
    "credits.clamav.db": "Database",
    "credits.clamav.db_text": "Firme virali mantenute da Cisco Talos, aggiornate ogni giorno con milioni di firme.",
    "credits.clamav.engine": "Motore di scansione",
    "credits.clamav.engine_text": "clamscan — Scanner a riga di comando per file e cartelle, in modo ricorsivo.",
    "credits.clamav.p1": "ClamAV è un motore antivirus open source progettato per rilevare trojan, virus, malware e altre minacce. È ampiamente usato sui server di posta e come soluzione antivirus sui sistemi Unix/Linux.",
    "credits.developer": "Sviluppatore",
    "credits.freshclam.auto": "Aggiornamento automatico",
    "credits.freshclam.auto_text": "Il servizio clamav-freshclam gira in background; ClamAV Antivirus GUI forza inoltre una verifica ogni giorno alle 07:00 e 5 minuti dopo ogni avvio.",
    "credits.freshclam.config": "Configurazione",
    "credits.freshclam.config_text": "Configurabile tramite /etc/clamav/freshclam.conf — frequenza, mirror, proxy, notifiche.",
    "credits.freshclam.db": "Database",
    "credits.freshclam.db_text": "main.cvd — Database principale. daily.cvd — Aggiornamenti quotidiani. bytecode.cvd — Firme bytecode avanzate.",
    "credits.freshclam.p1": "Freshclam è lo strumento di aggiornamento automatico dei database virali di ClamAV. Scarica le firme più recenti dai server mirror di ClamAV.",
    "credits.licence.appindicator": "Integrazione nella barra delle applicazioni per i desktop Linux (LGPL)",
    "credits.licence.distributed": "Distribuito con licenza",
    "credits.licence.gtk": "Toolkit grafico nativo per Linux (LGPL)",
    "credits.licence.p1": "ClamAV è distribuito con licenza GPL v2 (GNU General Public License versione 2). ClamAV è un progetto di Cisco Talos Intelligence Group.",
    "credits.licence.p2": "ClamAV Antivirus GUI (questa interfaccia grafica) è software libero distribuito con licenza GPL v3 (GNU General Public License versione 3), sviluppato da Dukiwi SA. L'interfaccia usa i seguenti componenti:",
    "credits.licence.webkit": "Motore di rendering web integrato per l'interfaccia HTML/CSS/JS (LGPL)",
    "credits.tab.licence": "Licenza",
