    "legal.footer": "Questo testo è disponibile anche in Crediti → Avvertenza.",
    "legal.link": "Avvertenza",
    "legal.p1": "ClamAV Antivirus GUI (di seguito «il Software») è fornito da Dukiwi SA «COSÌ COM'È» (as is) e «SECONDO DISPONIBILITÀ», senza alcuna garanzia di alcun tipo, espressa o implicita, incluse, a titolo non esaustivo, le garanzie di commerciabilità, idoneità a uno scopo particolare, non violazione di diritti, esattezza, affidabilità, disponibilità o assenza di errori. Installando o utilizzando il Software accetti senza riserve la presente avvertenza.",
    "legal.p10": "Dukiwi SA non garantisce la continuità, la durata né la frequenza degli aggiornamenti del Software, delle firme o delle fonti di informazione, e può interromperne la fornitura in qualsiasi momento senza preavviso né indennizzo. Il Software può contenere errori; ogni correzione è effettuata a discrezione di Dukiwi SA, senza obbligo.",
    "legal.p11": "Il Software integra o utilizza componenti di terzi (in particolare ClamAV, UFW, Lynis, unhide, chkrootkit, debsums, librerie Python e GTK) soggetti alle proprie licenze e condizioni. I marchi e i nomi di prodotto citati appartengono ai rispettivi proprietari. Dukiwi SA non è affiliata a Cisco Talos / ClamAV né responsabile di tali componenti.",
    "legal.p12": "Se una disposizione della presente avvertenza è ritenuta nulla o inapplicabile, le altre disposizioni restano pienamente in vigore e la disposizione interessata si considera sostituita da una disposizione valida di effetto equivalente. La presente avvertenza è regolata dal diritto svizzero; ogni controversia è di competenza esclusiva dei tribunali della sede di Dukiwi SA, fatte salve disposizioni imperative contrarie. Se non accetti queste condizioni, non installare e non utilizzare il Software.",
    "legal.p2": "Il Software è uno strumento di ausilio e costituisce al massimo una prima barriera. Si basa sul motore libero ClamAV, su database di firme e su fonti di informazione di terzi (Ubuntu, OSV.dev, liste di blocco, servizi di geolocalizzazione) su cui Dukiwi SA non esercita alcun controllo. Nessun antivirus, firewall o strumento di rilevamento può identificare tutte le minacce; malware nuovi o mirati possono non essere rilevati e programmi legittimi possono essere segnalati per errore (falsi positivi).",
    "legal.p3": "Un risultato «nessuna minaccia rilevata», un indicatore verde, un punteggio, un voto o qualsiasi altra informazione mostrata dal Software non costituiscono in alcun caso una garanzia che il tuo computer, i tuoi dati o la tua rete siano puliti, sicuri o conformi. Queste informazioni sono fornite a titolo puramente indicativo e non sostituiscono né un audit di sicurezza, né una supervisione professionale, né la tua vigilanza.",
    "legal.p4": "Solo un comportamento prudente e informato dell'utente (sensibilizzazione alla sicurezza) permette di limitare realmente i rischi: lettura attenta prima di cliccare, diffidenza verso i messaggi insoliti, rifiuto di allegati e supporti sconosciuti, password robuste, backup regolari e offline, installazione rapida degli aggiornamenti. L'utente resta l'unico responsabile delle proprie azioni, delle proprie scelte e della protezione dei propri dati.",
    "legal.p5": "NELLA MISURA MASSIMA CONSENTITA DALLA LEGGE APPLICABILE, DUKIWI SA, I SUOI AMMINISTRATORI, DIPENDENTI, MANDATARI, PARTNER E COLLABORATORI NON POTRANNO IN ALCUN CASO ESSERE RITENUTI RESPONSABILI di qualsiasi danno diretto, indiretto, incidentale, speciale, consequenziale, punitivo o esemplare, inclusi, a titolo non esaustivo: perdita, alterazione, cifratura o divulgazione di dati; perdita di profitti, fatturato, clientela o attività; interruzione dell'attività; costi di sostituzione; danno alla reputazione; derivanti da o connessi all'uso o all'impossibilità di usare il Software, anche se Dukiwi SA è stata informata della possibilità di tali danni.",
    "legal.p6": "Questa esclusione copre in particolare, senza limitazione: qualsiasi infezione da virus, worm, cavallo di Troia, ransomware (cryptolocker), spyware o altro codice malevolo, rilevato o meno; qualsiasi pirateria, intrusione, accesso non autorizzato, phishing, truffa del CEO, ingegneria sociale o furto d'identità; qualsiasi sfruttamento di una vulnerabilità di sicurezza, corretta o meno, nota o meno; qualsiasi perdita di dati conseguente a una quarantena, una cancellazione, l'arresto di un processo, una regola del firewall o qualsiasi altra azione avviata dal Software o dall'utente.",
    "legal.p7": "A seconda della configurazione scelta dall'utente, il Software può eseguire azioni con impatto sul sistema: sospensione o arresto di processi, quarantena o spostamento di file, attivazione del firewall e blocco di connessioni, installazione di aggiornamenti, blocco dell'accesso a supporti rimovibili. L'utente riconosce che queste azioni possono disturbare programmi legittimi o causare perdite di dati e se ne assume l'intera responsabilità. Spetta a lui disporre di backup completi e verificati prima di qualsiasi utilizzo.",
    "legal.p8": "Dukiwi SA non è responsabile di un uso inappropriato, negligente, improprio, illecito o contrario alla presente avvertenza del Software, né delle conseguenze della disattivazione, modifica o elusione delle sue protezioni da parte dell'utente, di un amministratore o di terzi. Il Software non deve essere usato come unica misura di protezione in un ambiente in cui un guasto potrebbe causare danni fisici, materiali, finanziari o ambientali.",
    "legal.p9": "Il Software non è progettato né certificato per garantire la conformità a qualsiasi obbligo legale, regolamentare o contrattuale (protezione dei dati, segreto professionale, norme di settore, requisiti assicurativi…). Spetta all'utente o alla sua organizzazione definire e attuare le misure di sicurezza adeguate alla propria situazione e verificarne l'adeguatezza.",
    "legal.title": "Avvertenza e limitazione di responsabilità",
