    "security.vulns.ack_all_msg": "Queste {n} vulnerabilità senza correzione non conteranno più nel colore dello scudo, nel punteggio di sicurezza né nella vista semplice. Restano elencate in « Vulnerabilità ignorate », dove puoi mostrarle di nuovo in qualsiasi momento. Le vulnerabilità pubblicate in seguito saranno sempre segnalate.",
