    "security.vulns.ack_intro": "Una vulnerabilità senza correzione che ritieni irrilevante per te può essere ignorata: non conta più nel colore dello scudo, nel punteggio né nella vista semplice, e resta consultabile in « Vulnerabilità ignorate ». Le vulnerabilità pubblicate in seguito vengono sempre mostrate.",
