    "security.vulns.acked_intro": "Ignorate da te: non contano più nello stato del sistema.",
    "security.vulns.acked_list": "Vulnerabilità ignorate ({n})",
    "security.vulns.cve.tunnelvision": "« TunnelVision »: difetto di progettazione del DHCP (opzione 121), non un bug di questo pacchetto; nessuna correzione possibile, Ubuntu la classifica « deferred ». Rischio solo su una rete non controllata (Wi-Fi pubblico) dove un falso server DHCP può deviare il traffico fuori dal tunnel. Hai una VPN configurata ({vpns}): su una rete pubblica, spegni il Wi-Fi se la VPN cade, oppure usa una VPN con kill switch (firewall che consente solo il server VPN).",
    "security.vulns.cve.tunnelvision_novpn": "« TunnelVision »: difetto di progettazione del DHCP (opzione 121), non un bug di questo pacchetto; nessuna correzione possibile, Ubuntu la classifica « deferred ». Riguarda solo le connessioni VPN, e nessuna VPN è configurata su questo computer: senza effetto in pratica.",
