    "security.vulns.hwe_badge": "corretta nel kernel HWE ({pkg})",
    "security.vulns.hwe_note": "{n} vulnerabilità riguardano il kernel 6.8 fornito con Linux Mint e sono già corrette in un kernel HWE più recente (6.11 o 6.14). Ubuntu non le correggerà tutte nel 6.8: la soluzione è installare il kernel HWE (Gestore degli aggiornamenti → Visualizza → Kernel Linux, oppure « sudo apt install linux-generic-hwe-24.04 »).",
    "security.vulns.intro": "«Senza correzione»: Ubuntu non ha ancora pubblicato una correzione per questo pacchetto in questa versione del sistema; non c'è nulla da installare e la maggior parte è di priorità media o bassa. Una vulnerabilità già corretta nella versione installata non compare. «Correzione disponibile»: un aggiornamento la installa.",
    "security.vulns.kernel_note": "{n} vulnerabilità riguardano il kernel in esecuzione ({src} {release}): Ubuntu non ha ancora pubblicato una correzione, verranno corrette dagli aggiornamenti di sistema, nulla da fare da parte tua. Non contano in « Senza correzione ».",
    "security.vulns.kernel_pending": "Kernel (correzione attesa)",
    "security.vulns.na_note": "{n} vulnerabilità riguardano {pkgs}: il motore JavaScript estratto da Firefox ESR, usato da {users}. Non è il tuo browser (Firefox si aggiorna a parte). Descrivono parti del browser assenti nel solo motore (contenuti web, animazioni, media, schede…) e Ubuntu non le corregge in questo pacchetto: non contano in « Senza correzione ». Le falle proprie del motore (JIT, WebAssembly, garbage collector) restano in « Senza correzione ».",
